document.getElementById('review-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('review-status');button.disabled=true;try{const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rating:Number(document.getElementById('review-rating').value),comment:document.getElementById('review-comment').value}),signal:AbortSignal.timeout(15000)}),data=await response.json();if(!response.ok)throw Error(data.error);status.textContent='평가를 저장했어. 의견 남겨 줘서 고마워!';button.textContent='제출 완료';}catch(error){status.textContent=error.message;button.disabled=false;}});
